def min_max(values):
    return min(values), max(values)

lowest, highest = min_max([4, 9, 2])
print(lowest, highest)

def greet(name):
    return f'Hello, {name}!'

print(greet('Asha'))

def total(price, quantity=1, tax_rate=0.05):
    subtotal = price * quantity
    return subtotal * (1 + tax_rate)

print(total(100, 2))

def add_all(*numbers):
    return sum(numbers)

print(add_all(2, 4, 6))

def show_profile(**details):
    for key, value in details.items():
        print(f'{key}: {value}')

show_profile(name='Asha', city='Hyderabad')

class Dog:
    def __init__(self, name):
        self.name = name

pet = Dog('Milo')
print(pet.name)

class BankAccount:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount

account = BankAccount('Asha')
account.deposit(500)
print(account.balance)

